import type {
  ProviderBCommitBatch,
  ProviderBReservationRow,
  ProviderBStorage,
  ProviderBStockRow,
  Reservation,
  Service,
  ServiceResponse,
  Stock,
} from "./types";
import { error } from "./reservation";
import {
  decodeDecimalText,
  isId,
  isQuantity,
  isRecord,
  isRevision,
  isUnits,
} from "./validation";

type Command =
  | { op: "getAvailability"; sku: string }
  | { op: "getReservation"; reservationId: string }
  | { op: "reserve"; reservationId: string; sku: string; quantity: number };

type ReadResult =
  | { kind: "found"; value: unknown }
  | { kind: "missing" }
  | { kind: "unavailable" };

function parseCommand(raw: unknown): Command | undefined {
  if (!isRecord(raw)) return undefined;
  switch (raw.op) {
    case "getAvailability":
      return isId(raw.sku) ? { op: raw.op, sku: raw.sku } : undefined;
    case "getReservation":
      return isId(raw.reservationId)
        ? { op: raw.op, reservationId: raw.reservationId } : undefined;
    case "reserve":
      return isId(raw.reservationId) && isId(raw.sku) && isQuantity(raw.quantity)
        ? { op: raw.op, reservationId: raw.reservationId, sku: raw.sku, quantity: raw.quantity }
        : undefined;
    default:
      return undefined;
  }
}

function classifyReadEnvelope(value: unknown): ReadResult {
  if (!isRecord(value) || typeof value.ok !== "boolean") return { kind: "unavailable" };
  if (value.ok) {
    return "value" in value && value.value !== null && value.value !== undefined
      ? { kind: "found", value: value.value }
      : { kind: "unavailable" };
  }
  if (!isRecord(value.error) || typeof value.error.reason !== "string") return { kind: "unavailable" };
  return value.error.reason === "NO_SUCH_KEY" ? { kind: "missing" } : { kind: "unavailable" };
}

function decimalText(value: number): string {
  return String(value);
}

function decodeStockRow(value: unknown, requestedKey: string): Stock | undefined {
  if (!isRecord(value) || !isId(value.itemKey) ||
      typeof value.onHandText !== "string" ||
      typeof value.heldText !== "string" ||
      typeof value.revisionText !== "string") {
    return undefined;
  }
  const totalUnits = decodeDecimalText(value.onHandText);
  const reservedUnits = decodeDecimalText(value.heldText);
  const revision = decodeDecimalText(value.revisionText);
  if (value.itemKey !== requestedKey ||
      totalUnits === undefined || reservedUnits === undefined || revision === undefined ||
      !isUnits(totalUnits) || !isUnits(reservedUnits) || reservedUnits > totalUnits ||
      !isRevision(revision)) {
    return undefined;
  }
  return { sku: value.itemKey, totalUnits, reservedUnits, revision };
}

function decodeReservationRow(value: unknown, requestedKey: string): Reservation | undefined {
  if (!isRecord(value) || !isId(value.bookingKey) || !isId(value.itemKey) ||
      typeof value.unitsText !== "string") {
    return undefined;
  }
  const quantity = decodeDecimalText(value.unitsText);
  if (value.bookingKey !== requestedKey || quantity === undefined || !isQuantity(quantity)) {
    return undefined;
  }
  return {
    reservationId: value.bookingKey,
    sku: value.itemKey,
    quantity,
  };
}

function reservationResponse(status: 200 | 201, reservation: Reservation): ServiceResponse {
  return {
    status,
    body: {
      reservationId: reservation.reservationId,
      sku: reservation.sku,
      quantity: reservation.quantity,
    },
  };
}

function stockRow(stock: Stock): ProviderBStockRow {
  return {
    itemKey: stock.sku,
    onHandText: decimalText(stock.totalUnits),
    heldText: decimalText(stock.reservedUnits),
    revisionText: decimalText(stock.revision),
  };
}

function reservationRow(reservation: Reservation): ProviderBReservationRow {
  return {
    bookingKey: reservation.reservationId,
    itemKey: reservation.sku,
    unitsText: decimalText(reservation.quantity),
  };
}

function commitBatch(stock: Stock, reservation: Reservation): ProviderBCommitBatch {
  return {
    expectedRevisionText: decimalText(stock.revision),
    stockRow: stockRow({
      ...stock,
      reservedUnits: stock.reservedUnits + reservation.quantity,
      revision: stock.revision + 1,
    }),
    reservationRow: reservationRow(reservation),
    outboxRows: [{
      key: "reservation.created:" + reservation.reservationId,
      category: "reservation",
      name: "created",
      payload: {
        bookingKey: reservation.reservationId,
        itemKey: reservation.sku,
        unitsText: decimalText(reservation.quantity),
      },
    }],
  };
}

export function createProviderBReservationService({ storage }: { storage: ProviderBStorage }): Service {
  return {
    async handle(raw): Promise<ServiceResponse> {
      const command = parseCommand(raw);
      if (command === undefined) return error(400, "invalid_command");
      try {
        if (command.op === "getAvailability") {
          const read = classifyReadEnvelope(await storage.read({ collection: "inventory", key: command.sku }));
          if (read.kind === "missing") return error(404, "stock_not_found");
          if (read.kind === "unavailable") return error(500, "storage_unavailable");
          const stock = decodeStockRow(read.value, command.sku);
          if (!stock) return error(500, "storage_unavailable");
          return {
            status: 200,
            body: {
              sku: stock.sku,
              totalUnits: stock.totalUnits,
              reservedUnits: stock.reservedUnits,
              availableUnits: stock.totalUnits - stock.reservedUnits,
            },
          };
        }

        const reservationRead = classifyReadEnvelope(await storage.read({
          collection: "reservations",
          key: command.reservationId,
        }));
        if (reservationRead.kind === "unavailable") return error(500, "storage_unavailable");
        const existing = reservationRead.kind === "found"
          ? decodeReservationRow(reservationRead.value, command.reservationId)
          : undefined;
        if (reservationRead.kind === "found" && !existing) return error(500, "storage_unavailable");
        if (command.op === "getReservation") {
          return existing ? reservationResponse(200, existing) : error(404, "reservation_not_found");
        }
        if (existing) {
          return existing.sku === command.sku && existing.quantity === command.quantity
            ? reservationResponse(200, existing)
            : error(409, "reservation_conflict");
        }

        const stockRead = classifyReadEnvelope(await storage.read({ collection: "inventory", key: command.sku }));
        if (stockRead.kind === "missing") return error(404, "stock_not_found");
        if (stockRead.kind === "unavailable") return error(500, "storage_unavailable");
        const stock = decodeStockRow(stockRead.value, command.sku);
        if (!stock) return error(500, "storage_unavailable");
        if (stock.totalUnits - stock.reservedUnits < command.quantity) {
          return error(409, "insufficient_stock");
        }
        const nextRevision = stock.revision + 1;
        if (!isRevision(nextRevision)) return error(500, "storage_unavailable");
        const reservation: Reservation = {
          reservationId: command.reservationId,
          sku: command.sku,
          quantity: command.quantity,
        };
        const outcome = await storage.commitBatch(commitBatch(stock, reservation));
        if (outcome === "revision_conflict") return error(409, "commit_conflict");
        if (outcome !== "applied") return error(500, "storage_unavailable");
        return reservationResponse(201, reservation);
      } catch {
        return error(500, "storage_unavailable");
      }
    },
  };
}

