import type { Service, ServiceResponse, StockReportSource } from "./types";
import { error } from "./reservation";
import { isId, isRecord, isUnits } from "./validation";

type LowStockCommand = { op: "lowStock"; belowUnits: number };

type SnapshotRow = {
  sku: string;
  totalUnits: number;
  reservedUnits: number;
};

function parseCommand(raw: unknown): LowStockCommand | undefined {
  if (!isRecord(raw) || raw.op !== "lowStock" || !isUnits(raw.belowUnits)) return undefined;
  return { op: "lowStock", belowUnits: raw.belowUnits };
}

function decodeSnapshotRow(value: unknown): SnapshotRow | undefined {
  if (!isRecord(value) || !isId(value.sku) || !isUnits(value.totalUnits) ||
      !isUnits(value.reservedUnits) || value.reservedUnits > value.totalUnits) {
    return undefined;
  }
  return {
    sku: value.sku,
    totalUnits: value.totalUnits,
    reservedUnits: value.reservedUnits,
  };
}

function decodeSnapshot(value: unknown): SnapshotRow[] | undefined {
  if (!Array.isArray(value)) return undefined;
  const seen = new Set<string>();
  const rows: SnapshotRow[] = [];
  for (const item of value) {
    const row = decodeSnapshotRow(item);
    if (!row || seen.has(row.sku)) return undefined;
    seen.add(row.sku);
    rows.push(row);
  }
  return rows;
}

export function createStockReport({ source }: { source: StockReportSource }): Service {
  return {
    async handle(raw): Promise<ServiceResponse> {
      const command = parseCommand(raw);
      if (!command) return error(400, "invalid_command");
      try {
        const snapshot = decodeSnapshot(await source.readSnapshot());
        if (!snapshot) return error(500, "storage_unavailable");
        const items = snapshot
          .map((row) => ({ sku: row.sku, availableUnits: row.totalUnits - row.reservedUnits }))
          .filter((row) => row.availableUnits < command.belowUnits)
          .sort((a, b) => a.sku < b.sku ? -1 : a.sku > b.sku ? 1 : 0);
        return { status: 200, body: { items } };
      } catch {
        return error(500, "storage_unavailable");
      }
    },
  };
}

